INSERT INTO `perguntas` VALUES (1,'O que significa a sigla HTML?','Hyper Text Markup Language','High Tech Modern Language','Hyper Link Transfer Method','Hyper Text Management Logic','a',1),(2,'Qual das seguintes linguagens é compilada diretamente para bytecode?','Python','C++','JavaScript','Java','d',1),(3,'Qual é a função do comando \"git clone\"?','Criar um repositório novo do zero','Copiar um repositório existente para a máquina local','Enviar alterações para o servidor','Apagar um ramo (branch) local','b',1),(4,'O que é o \"Garbage Collector\" no Java?','Um vírus que corrompe arquivos','Um componente que liberta memória de objetos não usados','Um depurador de código síncrono','Uma ferramenta de criptografia','b',1),(5,'Qual protocolo é usado de forma segura para navegar na Web?','HTTP','FTP','HTTPS','SSH','c',1),(6,'Qual destas estruturas de dados segue o conceito LIFO (Last In, First Out)?','Fila (Queue)','Pilha (Stack)','Lista Ligada','Tabela Hash','b',1),(7,'O que significa a sigla SQL?','Structured Query Language','Simple Queue List','Sequential Query Line','Standard Quantified Logic','a',1),(8,'Qual é a porta padrão utilizada pelo protocolo HTTP?','21','22','80','443','c',1),(9,'No Java, qual palavra-chave impede que uma classe seja herdada?','static','abstract','final','private','c',1),(10,'O que faz o operador \"%\" na maioria das linguagens de programação?','Calcula a percentagem de um número','Retorna o resto de uma divisão inteira','Eleva um número ao quadrado','Divide dois números reais','b',1),(11,'Qual destes não é um banco de dados relacional?','MySQL','PostgreSQL','MongoDB','Oracle DB','c',1),(12,'O que significa CSS no desenvolvimento web?','Computer Style Sheets','Creative Style Systems','Cascading Style Sheets','Complex Style Syntax','c',1),(13,'Qual das opções descreve um ataque de SQL Injection?','Inserir código SQL malicioso em campos de entrada do utilizador','Derrubar um servidor com múltiplos acessos falsos','Intercetar tráfego de rede Wi-Fi','Criptografar arquivos e pedir um resgate','a',1),(14,'No Java, qual é a superclasse de todas as outras classes?','String','Main','Object','Class','c',1),(15,'O que é um \"NullPointerException\"?','Um erro ao tentar aceder a um método/atributo de um objeto nulo','Um erro de falta de espaço em disco','Uma falha de ligação com a internet','Um erro de sintaxe no código','a',1),(16,'Qual comando SQL é usado para remover dados de uma tabela sem apagar a tabela?','DELETE','DROP','REMOVE','ALTER','a',1),(17,'O que significa a sigla API?','Application Programming Interface','Advanced Program Integration','Automated Processing Index','Applied Protocol Interface','a',1),(18,'Qual componente do computador é considerado o \"cérebro\", responsável pela execução de instruções?','Memória RAM','Disco Rígido (HDD)','Placa Gráfica (GPU)','Processador (CPU)','d',1),(19,'No Git, qual comando junta as alterações de um ramo noutro?','git push','git merge','git commit','git fork','b',1),(20,'Qual linguagem é predominantemente usada para adicionar interatividade em páginas web?','HTML','CSS','JavaScript','SQL','c',1),(21,'O que é a cloud computing (computação na nuvem)?','Processamento de dados usando satélites meteorológicos','Entrega de serviços de computação pela internet','Armazenamento de dados exclusivo em cartões de memória','Um tipo de inteligência artificial descentralizada','b',1),(22,'Qual o tipo primitivo no Java usado para armazenar um único caractere?','String','char','byte','boolean','b',1),(23,'Qual é a função principal de um Router (Roteador) na rede?','Armazenar arquivos dos utilizadores','Encaminhar pacotes de dados entre redes diferentes','Aumentar a velocidade do processador','Proteger contra quedas de energia','b',1),(24,'O que significa o acrónimo JSON?','JavaScript Object Notation','Java Source Open Network','Just System Output Node','Joint Software Optimization Network','a',1),(25,'Qual destes conceitos pertence à Programação Orientada a Objetos?','Recursividade estrita','Polimorfismo','Alocação manual de ponteiros','Compilação Just-In-Time','b',1),(26,'Em redes, o que faz o serviço DNS?','Criptografa senhas de utilizadores','Converte nomes de domínio (como google.com) em endereços IP','Controla a velocidade do download','Instala atualizações no sistema operativo','b',1),(27,'O que é um arquivo com a extensão .jar no Java?','Um arquivo de código fonte não compilado','Um arquivo compactado contendo classes Java prontas para execução','Um instalador exclusivo para Windows','Um arquivo de configuração de banco de dados','b',1),(28,'Qual dos seguintes é um sistema operativo de código aberto (open-source)?','Windows 11','macOS','Linux','iOS','c',1),(29,'O que faz a instrução \"break\" dentro de um laço (loop) em Java?','Interrompe o programa imediatamente','Salta para a próxima iteração do laço','Sai imediatamente do laço atual','Gera uma exceção de runtime','c',1),(30,'O que é uma chave primária (Primary Key) no banco de dados?','A senha de acesso do administrador','Uma coluna que identifica unicamente cada registo numa tabela','A primeira coluna de qualquer tabela','Um comando para ligar duas tabelas','b',1),(31,'Qual das alternativas representa um framework para desenvolvimento backend em Java?','React','Angular','Spring Boot','Vue.js','c',1),(32,'No desenvolvimento móvel, para qual sistema o Swift é nativo?','Android','Windows Phone','iOS','Linux Mobile','c',1),(33,'O que significa a sigla IDE?','Integrated Development Environment','Internal Data Engine','Interface Design Element','Instruction Deployment Extension','a',1),(34,'Qual a diferença entre Memória RAM e Armazenamento (SSD/HDD)?','A RAM é permanente e o SSD é volátil','A RAM é volátil (temporária) e o SSD é permanente','A RAM é mais lenta que o SSD','Não há diferença','b',1),(35,'O que é Docker?','Um editor de texto para programadores','Uma plataforma de containerização de software','Um tipo de cabo de rede de alta velocidade','Um banco de dados NoSQL','b',1),(36,'Qual o valor padrão de uma variável do tipo boolean em Java quando declarada como atributo de classe?','true','null','0','false','d',1),(37,'O que significa a sigla URL?','Universal Resource Locator','Uniform Resource Locator','Unified Registry Line','User Redirect Link','b',1),(38,'Qual o principal objetivo do protocolo FTP?','Enviar mensagens de e-mail','Transferir arquivos entre um cliente e um servidor','Criptografar tráfego web','Gerir endereços IP automaticamente','b',1),(39,'No Java, como se declara uma constante?','Usando a palavra-chave const','Usando a palavra-chave final','Usando a palavra-chave static apenas','Usando a palavra-chave stable','b',1),(40,'Qual método é o ponto de entrada de qualquer aplicação Java standalone?','public void start()','public static void main(String[] args)','private void init()','public static run()','b',1),(41,'O que é o Scrum no desenvolvimento de software?','Uma linguagem de programação funcional','Uma metodologia ágil para gestão de projetos','Um software de automação de testes','Um padrão de arquitetura de software','b',1),(42,'O que faz o comando SQL \"SELECT COUNT(*)\"?','Lista todas as linhas de uma tabela','Soma os valores numéricos de uma coluna','Retorna o número total de linhas que correspondem a um critério','Apaga os registos duplicados','c',1),(43,'Qual das seguintes linguagens é muito utilizada para Ciência de Dados e Inteligência Artificial?','PHP','Cobol','Python','C#','c',1),(44,'O que faz o comando \"git status\"?','Envia o código para o GitHub','Mostra o estado atual das alterações no diretório de trabalho','Apaga todos os arquivos não monitorizados','Cria um novo commit','b',1),(45,'O que significa a sigla IP nas redes de computadores?','Internet Protocol','Internal Process','Interconnected Port','Information Path','a',1),(46,'No contexto de POO, o que é uma Classe?','Um objeto em execução na memória','Um modelo ou molde a partir do qual os objetos são criados','Uma função matemática complexa','Um tipo de dado que só aceita números inteiros','b',1),(47,'Qual destas tags HTML é usada para criar uma hiperligação (link)?','<link>','<a>','<href>','<url>','b',1),(48,'O que é um Firewall?','Um dispositivo/software de segurança que monitoriza e filtra o tráfego de rede','Um acelerador de downloads de arquivos','Um sistema de refrigeração para servidores','Um vírus que queima componentes eletrónicos','a',1),(49,'No Java, qual coleção não permite elementos duplicados?','ArrayList','LinkedList','HashSet','Vector','c',1),(50,'O que faz o comando SQL \"ORDER BY\"?','Filtra os resultados com base numa condição','Agrupa os resultados por categorias','Ordena os resultados de uma consulta de forma ascendente ou descendente','Limita a quantidade de linhas retornadas','c',1),(51,'O que mede a Inflação?','O crescimento da população ativa','O aumento geral e contínuo dos preços de bens e serviços','A quantidade de ouro guardada num país','A taxa de desemprego jovem','b',2),(52,'O que é a Liquidez de um investimento?','A capacidade de transformar o investimento em dinheiro disponível sem perda significativa de valor','A rentabilidade líquida após o pagamento de impostos','O risco de perder todo o capital investido','O prazo mínimo contratual para resgate','a',2),(53,'O que representa uma Ação na bolsa de valores?','Um contrato de empréstimo feito a um banco','A menor parcela do capital social de uma empresa (copropriedade)','Um título de dívida pública emitido pelo governo','Um seguro contra a falência empresarial','b',2),(54,'O que significa a sigla PIB?','Produto Interno Bruto','Plano de Investimento Bancário','Património Líquido Individual','Preço de Importação de Bens','a',2),(55,'Qual é a principal característica da Renda Fixa?','As regras de rendimento são definidas no momento da aplicação','O rendimento varia diariamente e pode ser negativo','É um investimento exclusivo para grandes empresas','Não possui qualquer tipo de garantia ou segurança','a',2),(56,'O que é a Diversificação de investimentos?','Colocar todo o dinheiro no ativo de maior rentabilidade','Distribuir o capital por diferentes tipos de ativos para reduzir o risco','Mudar de banco todas as semanas','Investir apenas em moedas estrangeiras físicas','b',2),(57,'O que são Dividendos?','Impostos pagos pelos cidadãos sobre os seus salários','Parte dos lucros de uma empresa distribuída aos seus acionistas','Multas cobradas por atrasos no pagamento de empréstimos','Taxas administrativas cobradas por fundos de investimento','b',2),(58,'O que caracteriza a Renda Variável?','O retorno não pode ser previsto e varia conforme as oscilações do mercado','Garante sempre lucros fixos todos os meses','O governo cobre todas as perdas caso o mercado caia','Só permite investimentos de curto prazo (até 30 dias)','a',2),(59,'O que é um Orçamento Familiar?','Um registo detalhado de receitas e despesas para planeamento financeiro','Um pedido de empréstimo para comprar habitação','O valor total de impostos que uma família deve pagar ao ano','A soma de todos os bens físicos de uma casa','a',2),(60,'O que é a Taxa de Juro?','O preço do dinheiro no tempo, cobrado pelo empréstimo ou pago pela aplicação','Uma taxa cobrada apenas em transações internacionais','O valor fixo cobrado para abrir uma conta bancária','A percentagem de lucro que as empresas pagam aos trabalhadores','a',2),(61,'O que acontece ao poder de compra quando a inflação sobe significativamente?','Aumenta, pois o dinheiro passa a valer mais','Diminui, pois são necessárias mais unidades de moeda para comprar o mesmo item','Mantém-se inalterado','Garante estabilidade económica imediata','b',2),(62,'O que significa o termo \"Bear Market\" no mercado financeiro?','Um período de forte valorização e otimismo nas bolsas','Um mercado focado exclusivamente na comercialização de commodities','Um período de queda acentuada e prolongada nos preços das ações','A abertura de uma nova bolsa de valores','c',2),(63,'O que significa o termo \"Bull Market\"?','Um mercado em forte tendência de alta e otimismo','Um mercado em recessão profunda','O encerramento diário das atividades da bolsa','Um mercado regulado apenas pelo Banco Central','a',2),(64,'O que é o Fundo de Emergência?','Um investimento de altíssimo risco focado no longo prazo','Uma reserva financeira para cobrir imprevistos e despesas urgentes','Um subsídio pago pelo governo a empresas em falência','O capital usado para abrir uma nova empresa','b',2),(65,'Qual a diferença entre Juros Simples e Juros Compostos?','Os simples rendem mais que os compostos no longo prazo','Os simples incidem apenas sobre o capital inicial; os compostos incidem sobre o capital acumulado (juros sobre juros)','Os compostos são ilegais em quase todo o mundo','Não há diferença matemática entre eles','b',2),(66,'O que é uma Obrigação (Título de Dívida)?','Um título onde o investidor empresta dinheiro a uma entidade (Estado ou empresa) em troca de juros','O direito de voto nas assembleias de uma empresa','Um imposto obrigatório sobre movimentações financeiras','O contrato de compra de um imóvel à vista','a',2),(67,'O que é o \"Spread\" bancário?','A taxa de juro real descontada a inflação','A diferença entre a taxa que o banco paga ao captar dinheiro e a taxa que cobra ao emprestar','O limite máximo de crédito atribuído a um cliente','O horário de funcionamento dos mercados financeiros','b',2),(68,'O que mede o perfil de investidor (Sustentável, Moderado, Arrojado)?','O nível de tolerância ao risco e os objetivos financeiros do investidor','A quantidade total de património que o investidor possui','A idade e a profissão atual do utilizador','O número de contas bancárias ativas','a',2),(69,'O que é a Capitalização de Mercado de uma empresa?','O total de dinheiro guardado no cofre da empresa','O valor total das ações da empresa em circulação na bolsa (preço da ação vezes o número de ações)','O lucro líquido registado no último ano','O valor pago em impostos federais','b',2),(70,'O que significa \"Ativo\" no balanço patrimonial?','Tudo aquilo que gera despesas e saídas de dinheiro','Bens, direitos e investimentos que possuem valor económico e podem gerar benefícios futuros','As dívidas acumuladas com fornecedores','O salário mensal bruto de um trabalhador','b',2),(71,'O que significa \"Passivo\" no balanço patrimonial?','Os investimentos com retorno garantido no curto prazo','Obrigações financeiras, dívidas e despesas que a entidade tem de pagar','Os lucros reinvestidos na própria estrutura','Bens móveis de uso diário da empresa','b',2),(72,'O que é o Lucro Líquido?','O total de receitas geradas por uma venda sem descontar nada','O valor que sobra das receitas após deduzir todos os custos, despesas e impostos','O dinheiro investido em pesquisa e desenvolvimento','A soma de todos os salários da administração','b',2),(73,'O que é a Receita Bruta?','O lucro final guardado no banco pelos acionistas','O valor total arrecadado com as vendas de bens ou serviços num período, antes de qualquer dedução','O prejuízo operacional acumulado no trimestre','O imposto pago na faturação de produtos','b',2),(74,'O que é o \"Day Trade\"?','A compra e venda de um mesmo ativo financeiro no mesmo dia','Um investimento focado estritamente na reforma (aposentadoria)','A negociação de criptomoedas durante o fim de semana','Um tipo de poupança automática de longo prazo','a',2),(75,'Qual a principal função de um Banco Central?','Vender ações de empresas privadas ao público','Garantir crédito barato para todos os cidadãos sem critérios','Conduzir a política monetária, emitir moeda e zelar pela estabilidade do sistema financeiro','Financiar campanhas de marketing de bancos comerciais','c',2),(76,'O que significa a sigla ROI?','Return on Investment (Retorno sobre o Investimento)','Rate of Inflation (Taxa de Inflação)','Risk of Insolvency (Risco de Insolvência)','Return on Insurance (Retorno sobre Seguro)','a',2),(77,'O que é o Risco de Crédito?','O risco de o mercado de ações cair abruptamente','O risco de o tomador do empréstimo não cumprir as suas obrigações de pagamento (incumprimento)','O risco de a inflação corroer o rendimento','A taxa cobrada para transferir dinheiro entre contas','b',2),(78,'O que é a Taxa de Câmbio?','O preço de uma moeda expresso em termos de outra moeda','A taxa cobrada para efetuar pagamentos com cartão de débito','O juro cobrado no financiamento de veículos','O valor pago para registar uma patente comercial','a',2),(79,'O que é um \"Ativo de Refúgio\" (Safe Haven)?','Um ativo de altíssimo risco que promete lucros rápidos','Um ativo que tende a manter ou aumentar o seu valor durante períodos de crise económica (ex: Ouro)','Uma conta bancária secreta no estrangeiro','Um empréstimo de curto prazo sem juros','b',2),(80,'O que significa o termo \"Default\"?','O pagamento antecipado de todas as prestações de uma dívida','A situação de incumprimento de uma obrigação financeira (calote ou falha de pagamento)','A abertura de capital de uma empresa na bolsa','A fusão de dois grandes bancos comerciais','b',2),(81,'O que é o Mercado Primário na bolsa?','Onde os investidores negociam ações entre si','Onde as empresas emitem e vendem novas ações ou títulos ao público pela primeira vez (ex: IPO)','O mercado restrito à venda de matérias-primas agrícolas','A negociação exclusiva de moedas digitais','b',2),(82,'O que é o Mercado Secundário na bolsa?','Onde as empresas emitem novas ações para captar recursos','Onde os investidores compram e vendem ativos entre si, sem a participação direta da empresa emitente','O mercado secundário de peças de computadores','A negociação que ocorre fora do horário bancário','b',2),(83,'O que são Commodities?','Ações de empresas do setor tecnológico de ponta','Matérias-primas brutas ou produtos agrícolas padronizados negociados globalmente (ex: petróleo, ouro, café)','Contratos de seguros de vida internacionais','Impostos municipais sobre o comércio','b',2),(84,'O que é o IPCA (ou taxas de índice de preços semelhantes)?','Um indicador que mede a variação de preços para o consumidor final (Métrica de Inflação)','O imposto sobre a propriedade de veículos automóveis','O índice que mede o desempenho das maiores ações da bolsa','A taxa de juros cobrada nos cartões de crédito','a',2),(85,'O que caracteriza uma Empresa de Capital Aberto?','Uma empresa cujo capital pertence exclusivamente ao Estado','Uma empresa cujas ações estão registadas e podem ser negociadas na Bolsa de Valores','Uma empresa que não precisa de pagar impostos comerciais','Uma start-up que funciona em regime de coworking','b',2),(86,'O que é a \"Regra de Ouro\" das finanças pessoais?','Gastar sempre mais do que se ganha para estimular a economia','Gastar menos do que se ganha e investir a diferença com consistência','Investir todo o capital disponível em lotarias mundiais','Nunca utilizar cartões de débito ou transferências bancárias','b',2),(87,'O que é o \"Juro de Mora\"?','Um desconto concedido por pagamentos antecipados','Uma taxa de juro cobrada como penalidade pelo atraso no pagamento de uma obrigação','O juro pago em contas de poupança tradicionais','O valor cobrado para fazer a manutenção anual de contas','b',2),(88,'O que significa o termo Liquidez Reduzida?','Dificuldade em vender um ativo rapidamente pelo preço de mercado sem sofrer perdas pesadas','O lucro recorde apresentado por uma instituição financeira','O encerramento automático de contas por falta de uso','A isenção total de impostos num investimento','a',2),(89,'O que é um Fundo de Investimento?','Uma conta poupança individual num banco estatal','Uma comunhão de recursos de vários investidores gerida por um profissional para comprar uma carteira de ativos','Um empréstimo de alto valor concedido a governos estrangeiros','A receita arrecadada com coimas de trânsito','b',2),(90,'O que significa a sigla ETF?','Exchange Traded Fund (Fundo negociado em Bolsa que replica um índice)','Economic Transfer Foundation','Electronic Trade Finance','Estimated Tax Forecast','a',2),(91,'O que mede a volatilidade de uma ação?','O número total de investidores que compraram a ação num ano','A intensidade e a frequência das variações no preço dessa ação num período','A quantidade de filiais que a empresa possui no estrangeiro','O valor dos dividendos pagos no último mês','b',2),(92,'O que é um Financiamento Imobiliário?','Um empréstimo de curto prazo para comprar eletrodomésticos','Um contrato de crédito de longo prazo destinado à aquisição de habitação, onde o próprio imóvel serve de garantia','O aluguer temporário de um espaço comercial','O subsídio estatal para a reconstrução de estradas','b',2),(93,'O que é a TAEG no crédito ao consumo?','A Taxa Anual Efetiva Global, que reflete o custo total do crédito para o cliente (incluindo juros, taxas e seguros)','A Taxa de Amortização Exclusiva do Governo','A Tarifa Administrativa Extraordinária de Gestão','O imposto fixo cobrado sobre transferências internacionais','a',2),(94,'O que significa amortizar uma dívida?','Aumentar o prazo de pagamento cobrando mais juros','Efetuar pagamentos para reduzir o valor em dívida do capital inicial emprestado','Declarar falência para não pagar o valor acordado','Vender a dívida a outra instituição bancária','b',2),(95,'O que são \"Penny Stocks\"?','Ações de altíssimo valor de grandes multinacionais','Ações negociadas a valores muito baixos (geralmente cêntimos), associadas a alto risco e volatilidade','Títulos de dívida emitidos por pequenos municípios','Moedas de ouro colecionáveis de edição limitada','b',2),(96,'O que significa o termo \"Insolvência\"?','A capacidade de pagar todas as contas antes do prazo','A situação em que o total do passivo (dívidas) supera o total do ativo, impossibilitando o cumprimento de obrigações','O registo de patentes de uma empresa de sucesso','A abertura de um novo ramo de negócios no estrangeiro','b',2),(97,'O que é a Euribor?','A moeda digital oficial criada pela União Europeia','A taxa de juro de referência média à qual uma seleção de grandes bancos europeus empresta dinheiro entre si','O índice que mede a inflação anual em África','O imposto cobrado sobre transações bolsistas na Europa','b',2),(98,'O que significa a sigla Selic ou taxas básicas semelhantes nos países?','A taxa básica de juros da economia definida pelo banco central para controlar a inflação','O imposto sobre grandes fortunas individuais','O fundo de garantia para trabalhadores despedidos','A taxa de importação de componentes eletrónicos','a',2),(99,'O que é o Capital de Giro (ou Fundo de Maneio)?','O dinheiro necessário para financiar a continuidade das operações diárias de uma empresa (como pagar salários e fornecedores)','O investimento inicial feito pelos sócios para fundar a empresa','O lucro total que é distribuído no final do ano em dividendos','O património líquido imobiliário da empresa (edifícios e terrenos)','a',2),(100,'O que é a Previdência Privada/Complementar?','Um plano de seguros de saúde obrigatório por lei','Um fundo de investimento de longo prazo focado em garantir uma renda extra para a reforma (aposentadoria)','O sistema público de pensões gerido pela segurança social','O empréstimo bancário concedido a idosos','b',2),(101,'Se todo o quadrado é um retângulo, e todo o retângulo é um quadrilátero, o que se conclui?','Nenhum quadrado é quadrilátero','Todo o quadrado é um quadrilátero','Alguns retângulos não são quadriláteros','Nenhum retângulo é quadrado','b',3),(102,'Se a proposição P é verdadeira (V) e Q é falsa (F), qual o valor lógico de \"P E Q\" (conjunção)?','Verdadeira','Falsa','Inconclusiva','Nula','b',3),(103,'Se a proposição P é verdadeira (V) e Q é falsa (F), qual o valor lógico de \"P OU Q\" (disjunção)?','Verdadeira','Falsa','Inconclusiva','Nula','a',3),(104,'Qual é a negação lógica da afirmação \"Nenhum programador gosta de café\"?','Todos os programadores gostam de café','Algum programador gosta de café','Se gosta de café, não é programador','Nenhum programador gosta de chá','b',3),(105,'Uma condicional (P -> Q) só é FALSA quando:','P é falsa e Q é verdadeira','P é verdadeira e Q é falsa','Ambas são verdadeiras','Ambas são falsas','b',3),(106,'Se \"Se chover, a rua fica molhada\" é verdade, e sabemos que \"a rua não está molhada\", o que se conclui?','Está a chover muito','Não choveu','Vai chover amanhã','A rua foi limpa','b',3),(107,'Qual o próximo número na sequência lógica: 2, 4, 8, 16, ...?','20','24','32','64','c',3),(108,'Qual o próximo número na sequência de Fibonacci: 1, 1, 2, 3, 5, 8, ...?','10','12','13','15','c',3),(109,'Se três gatos caçam três ratos em três minutos, quantos minutos demora um gato a caçar um rato?','1 minuto','3 minutos','9 minutos','0 minutos','b',3),(110,'O pai do padre é o único filho do meu pai. Quem sou eu?','O avô do padre','O próprio padre','O pai do padre','O irmão do padre','c',3),(111,'Se um tijolo pesa 1 kg mais meio tijolo, quanto pesa um tijolo inteiro?','1.5 kg','2 kg','3 kg','4 kg','b',3),(112,'Qual é a negação da afirmação \"O carro é branco OU o casaco é azul\"?','O carro não é branco ou o casaco não é azul','O carro não é branco e o casaco não é azul','Se o carro não é branco, o casaco é azul','O carro é preto e o casaco é verde','b',3),(113,'Qual é a negação da afirmação \"Pedro é alto E Maria é inteligente\"?','Pedro não é alto e Maria não é inteligente','Pedro não é alto ou Maria não é inteligente','Pedro é baixo e Maria é ignorante','Se Pedro é alto, Maria não é inteligente','b',3),(114,'Se todos os peixes sabem nadar e alguns animais aquáticos são peixes, conclui-se que:','Todos os animais aquáticos sabem nadar','Alguns animais aquáticos sabem nadar','Nenhum animal aquático sabe nadar','Os peixes não são animais aquáticos','b',3),(115,'Numa sala há 4 cantos, em cada canto está um gato. Cada gato vê 3 gatos. Quantos gatos estão na sala?','12','4','3','7','b',3),(116,'Se amanhã eu disser \"ontem foi anteontem de terça-feira\", que dia é hoje?','Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','b',3),(117,'A equivalência lógica da condicional (P -> Q) pelo conceito de contrapositiva é:','Q -> P','~P -> ~Q','~Q -> ~P','P E ~Q','c',3),(118,'Se \"Se estudar, passo no exame\" é verdade, qual das opções é logicamente equivalente?','Se não estudar, não passo no exame','Se não passei no exame, não estudei','Passei no exame porque estudei','Estudei e não passei no exame','b',3),(119,'Uma bicondicional (P <-> Q) é VERDADEIRA quando:','P é verdadeira e Q é falsa','P é falsa e Q é verdadeira','Ambas têm o mesmo valor lógico (ambas V ou ambas F)','As duas são falsas apenas','c',3),(120,'Se dois pintores pintam uma casa em 4 dias, quantos dias demoram 4 pintores nas mesmas condições?','8 dias','2 dias','4 dias','1 dia','b',3),(121,'Se \"Alguns matemáticos são poetas\" e \"Todos os poetas são criativos\", então:','Todos os matemáticos são criativos','Alguns matemáticos são criativos','Nenhum matemático é criativo','Nenhum poeta é criativo','b',3),(122,'Descubra o padrão e complete: 1, 4, 9, 16, 25, ...?','30','35','36','49','c',3),(123,'Se mentir é sempre errado e João mentiu para salvar uma vida, logicamente:','João não errou','João cometeu um ato errado de acordo com a premissa','A premissa tornou-se falsa','Salvar vidas é sempre errado','b',3),(124,'Qual é o valor lógico da proposição composta (~V OU F)?','Verdadeira','Falsa','Nula','Inconclusiva','b',3),(125,'O que é uma Tautologia na lógica matemática?','Uma proposição composta que é sempre falsa','Uma proposição composta cujo valor lógico é sempre verdadeiro, independentemente dos valores das componentes','Uma frase sem sentido matemático','Uma contradição de argumentos','b',3),(126,'O que é uma Contradição na lógica matemática?','Uma proposição que pode ser verdadeira ou falsa','Uma proposição composta que é sempre falsa, independentemente dos valores das suas componentes','Um argumento correto com conclusão falsa','A negação de uma tautologia que resulta em algo inconclusivo','b',2),(127,'Se um número composto N é divisível por 2 e por 3, ele é obrigatoriamente divisível por:','5','6','9','12','b',3),(128,'Análise o argumento: \"Todas as aves voam. O pinguim é uma ave. Logo, o pinguim voa.\" Este argumento é:','Válido e verdadeiro','Válido, mas tem uma premissa falsa (nem todas as aves voam), gerando uma conclusão falsa','Inválido na sua estrutura lógica','Uma tautologia perfeita','b',3),(129,'Qual o próximo número na sequência: 3, 6, 12, 24, 48, ...?','50','60','96','100','c',3),(130,'Considere a frase: \"Se fores ao mercado, compra leite\". Quem foi ao mercado e NÃO comprou leite cometeu uma:','Verdade lógica','Violação da condicional (falsidade)','Tautologia','Equivalência perfeita','b',3),(131,'Se \"Nenhum mamífero tem guelras\" e \"A baleia é um mamífero\", conclui-se que:','A baleia tem guelras','A baleia não tem guelras','Algumas baleias têm guelras','O pinguim é um peixe','b',3),(132,'Qual é a negação lógica da frase \"Todos os alunos passaram\"?','Nenhum aluno passou','Pelo menos um aluno não passou','Todos os alunos chumbaram','Os alunos que passaram são inteligentes','b',3),(133,'Se p -> q é verdade, e q -> r é verdade, então p -> r é verdade. Esta propriedade chama-se:','Silogismo Hipotético','Modus Ponens','Modus Tollens','Dupla Negação','a',3),(134,'O argumento \"Se tenho dinheiro, viajo. Tenho dinheiro. Logo, viajo\" baseia-se na regra:','Modus Tollens','Modus Ponens','Silogismo Disjuntivo','Contradição','b',3),(135,'O argumento \"Se chover, o jogo é cancelado. O jogo não foi cancelado. Logo, não choveu\" baseia-se em:','Modus Ponens','Modus Tollens','Indução Completa','Falácia da afirmação do consequente','b',3),(136,'Se \"X > 5\" e \"Y < 3\", o que se pode afirmar com certeza sobre \"X - Y\"?','X - Y é menor que 2','X - Y é igual a 2','X - Y é maior que 2','X - Y é negativo','c',3),(137,'Qual o valor lógico de uma proposição verdadeira unida a qualquer outra proposição através do operador \"OU\"?','Sempre Falsa','Depende da outra proposição','Sempre Verdadeira','Nula','c',3),(138,'Qual o valor lógico de uma proposição falsa unida a qualquer outra proposição através do operador \"E\"?','Sempre Falsa','Sempre Verdadeira','Depende da outra proposição','Inconclusiva','a',3),(139,'Se num grupo de 5 pessoas, 3 gostam de lógica e 4 gostam de matemática, pelo menos quantas gostam de AMBAS?','0','1','2','3','c',3),(140,'Qual o próximo termo da sequência: 1, 3, 7, 15, 31, ...?','45','50','63','60','c',3),(141,'Se \"A é mais velho que B\" e \"B é mais velho que C\", o que se conclui logicamente?','C é mais velho que A','A é mais velho que C','A e C têm a mesma idade','B é o mais velho de todos','b',3),(142,'A negação da frase \"O suspeito é culpado E tem um cúmplice\" pela Lei de De Morgan é:','O suspeito não é culpado e não tem cúmplice','O suspeito não é culpado ou não tem cúmplice','Se o suspeito é culpado, não tem cúmplice','O suspeito é inocente e tem cúmplice','b',3),(143,'O que é uma falácia lógica?','Um argumento matematicamente perfeito com números primos','Um erro de raciocínio que invalida a consistência lógica de um argumento','Uma equação sem solução no conjunto dos reais','A definição correta de um axioma','b',3),(144,'Se \"Nenhum quadrado é círculo\" é verdadeiro, qual a relação inversa?','Todo o círculo é quadrado','Nenhum círculo é quadrado','Alguns círculos são quadrados','Todos os quadrados são esferas','b',3),(145,'Se numa caixa estão 5 bolas vermelhas e 5 azuis, quantas bolas preciso de retirar (no mínimo, às escuras) para ter a certeza de ter duas da mesma cor?','2','3','5','6','b',3),(146,'Qual o próximo número na sequência: 10, 20, 15, 30, 25, 50, ...?','40','45','60','100','b',3),(147,'Se uma afirmação P implica Q, dizemos que P é condição ______ para Q.','Suficiente','Necessária','Inútil','Equivalente','a',3),(148,'Se uma afirmação P é implicada por Q (Q -> P), dizemos que P é condição ______ para Q.','Suficiente','Necessária','Incompatível','Nula','b',3),(149,'S